<script setup>
import {onMounted,computed,ref} from 'vue';import{RouterLink}from'vue-router';import{api}from'../services/api';import{useJob}from'../composables/useJob';import JobStatus from '../components/JobStatus.vue'
const detail=ref(null),providers=ref([]),selected=ref(''),provider=ref('ollama'),status=ref(''),busy=ref(false),active=ref(false);const units=computed(()=>detail.value?.structure?.units||[]);const{job,refresh}=useJob()
async function load(){const project=await api.projectStatus();active.value=project.active===true;if(!active.value){status.value='No hay un proyecto activo. Regresa a Proyectos y abre uno.';return}detail.value=await api.projectDetail();providers.value=(await api.providerStatus()).providers||[];selected.value=units.value[0]?.id||'';refresh()}async function generate(){busy.value=true;status.value='Generando propuesta y extrayendo imágenes…';try{status.value=(await api.generate({unit_id:selected.value,provider:provider.value})).message||'Propuesta en cola.';refresh()}catch(e){status.value=e.message}finally{busy.value=false}}async function validate(){try{const r=await api.validate(selected.value);status.value=r.status==='pass'?'DTBook válido para auditoría humana.':(r.errors||[]).join(' · ')||'Pendiente'}catch(e){status.value=e.message}}onMounted(load)
</script>
<template><section class="hero"><span class="eyebrow">PASO 1 · LECCIONES</span><h2>Generar y auditar DTBook</h2><p>Selecciona una unidad, genera su propuesta y abre la auditoría página por página.</p></section><p v-if="!active" class="notice">{{status}}</p><template v-else><JobStatus :job="job"/><section class="library-card lesson-controls"><label>Unidad activa<select v-model="selected"><option v-for="unit in units" :key="unit.id" :value="unit.id">{{unit.name||unit.file}}</option></select></label><label>Proveedor<select v-model="provider"><option v-for="item in providers.filter(p=>p.available)" :value="item.id">{{item.label}}</option></select></label><div class="button-row"><button :disabled="busy||!selected" @click="generate">{{busy?'Generando…':'Generar propuesta'}}</button><button class="secondary" :disabled="!selected" @click="validate">Validar DTBook</button><RouterLink v-if="selected" class="button-link" :to="`/unit/${encodeURIComponent(selected)}`">Abrir auditoría visual</RouterLink></div><p v-if="status" class="notice">{{status}}</p></section></template></template>
